-- schema.sql
-- The whole schema in one file, for reading. Generated by `npm run db:schema` from
-- packages/db/migrations: don't edit it by hand. Add a migration, then regenerate.
-- Real databases are built by the migrations only. This file loads into an empty database.

CREATE EXTENSION IF NOT EXISTS citext WITH SCHEMA public;

CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

CREATE OR REPLACE FUNCTION notify_alert_created() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_notify('alert_created', NEW.user_id || ':' || NEW.id);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

CREATE TABLE IF NOT EXISTS alerts (
    id bigint NOT NULL,
    user_id bigint NOT NULL,
    user_filter_id bigint NOT NULL,
    listing_id bigint NOT NULL,
    listing_version_id bigint,
    alert_type text NOT NULL,
    channel text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    dedupe_key text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    matched_at timestamp with time zone DEFAULT now() NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    match_reasons_json jsonb,
    cluster_fingerprint character(64),
    CONSTRAINT alerts_alert_type_check CHECK ((alert_type = ANY (ARRAY['new_match'::text, 'price_drop'::text, 'price_change'::text, 'score_upgrade'::text, 'status_change'::text, 'digest'::text, 'source_degraded'::text]))),
    CONSTRAINT alerts_channel_check CHECK ((channel = ANY (ARRAY['in_app'::text, 'email'::text, 'push'::text, 'webhook'::text]))),
    CONSTRAINT alerts_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'sent'::text, 'failed'::text, 'dismissed'::text, 'opened'::text, 'suppressed'::text])))
);

