    overall_score numeric(5,2) NOT NULL,
    district_price_score numeric(5,2) NOT NULL,
    undervaluation_score numeric(5,2) NOT NULL,
    keyword_signal_score numeric(5,2) NOT NULL,
    time_on_market_score numeric(5,2) NOT NULL,
    confidence_score numeric(5,2) NOT NULL,
    district_baseline_ppsqm_eur numeric(12,2),
    bucket_baseline_ppsqm_eur numeric(12,2),
    discount_to_district_pct numeric(8,4),
    discount_to_bucket_pct numeric(8,4),
    matched_positive_keywords text[] DEFAULT ARRAY[]::text[] NOT NULL,
    matched_negative_keywords text[] DEFAULT ARRAY[]::text[] NOT NULL,
    explanation jsonb DEFAULT '{}'::jsonb NOT NULL,
    scored_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    location_score numeric(5,2),
    baseline_fallback_level text,
    baseline_sample_size integer,
    baseline_freshness_hours numeric,
    CONSTRAINT listing_scores_confidence_score_check CHECK (((confidence_score >= (0)::numeric) AND (confidence_score <= (100)::numeric))),
    CONSTRAINT listing_scores_district_price_score_check CHECK (((district_price_score >= (0)::numeric) AND (district_price_score <= (100)::numeric))),
    CONSTRAINT listing_scores_keyword_signal_score_check CHECK (((keyword_signal_score >= (0)::numeric) AND (keyword_signal_score <= (100)::numeric))),
    CONSTRAINT listing_scores_location_score_check CHECK (((location_score IS NULL) OR ((location_score >= (0)::numeric) AND (location_score <= (100)::numeric)))),
    CONSTRAINT listing_scores_overall_score_check CHECK (((overall_score >= (0)::numeric) AND (overall_score <= (100)::numeric))),
    CONSTRAINT listing_scores_score_version_check CHECK ((score_version > 0)),
    CONSTRAINT listing_scores_time_on_market_score_check CHECK (((time_on_market_score >= (0)::numeric) AND (time_on_market_score <= (100)::numeric))),
    CONSTRAINT listing_scores_undervaluation_score_check CHECK (((undervaluation_score >= (0)::numeric) AND (undervaluation_score <= (100)::numeric)))
);

