    CONSTRAINT listing_versions_list_price_eur_cents_check CHECK (((list_price_eur_cents IS NULL) OR (list_price_eur_cents >= 0))),
    CONSTRAINT listing_versions_listing_status_check CHECK ((listing_status = ANY (ARRAY['active'::text, 'inactive'::text, 'sold'::text, 'rented'::text, 'withdrawn'::text, 'expired'::text, 'unknown'::text]))),
    CONSTRAINT listing_versions_living_area_sqm_check CHECK (((living_area_sqm IS NULL) OR (living_area_sqm > (0)::numeric))),
    CONSTRAINT listing_versions_version_no_check CHECK ((version_no > 0)),
    CONSTRAINT listing_versions_version_reason_check CHECK ((version_reason = ANY (ARRAY['first_seen'::text, 'price_change'::text, 'content_change'::text, 'status_change'::text, 'relist_detected'::text, 'backfill'::text])))
