CREATE TABLE IF NOT EXISTS listings (
    id bigint NOT NULL,
    listing_uid uuid DEFAULT gen_random_uuid() NOT NULL,
    source_id bigint NOT NULL,
    source_listing_key text NOT NULL,
    source_external_id text,
    current_raw_listing_id bigint NOT NULL,
    latest_scrape_run_id bigint NOT NULL,
    canonical_url text NOT NULL,
    operation_type text NOT NULL,
    property_type text NOT NULL,
    property_subtype text,
    listing_status text DEFAULT 'active'::text NOT NULL,
    source_status_raw text,
    title text NOT NULL,
    description text,
    district_no smallint,
    district_name text,
    postal_code character varying(4),
    city text NOT NULL,
    federal_state text,
    street text,
    house_number text,
    address_display text,
    latitude numeric(9,6),
    longitude numeric(9,6),
    geocode_precision text,
    cross_source_fingerprint character(64),
    list_price_eur_cents bigint,
    monthly_operating_cost_eur_cents bigint,
    reserve_fund_eur_cents bigint,
    commission_eur_cents bigint,
    living_area_sqm numeric(10,2),
    usable_area_sqm numeric(10,2),
    balcony_area_sqm numeric(10,2),
    terrace_area_sqm numeric(10,2),
    garden_area_sqm numeric(10,2),
    rooms numeric(4,1),
    floor_label text,
    floor_number smallint,
    year_built integer,
    condition_category text,
    heating_type text,
    energy_certificate_class text,
    has_balcony boolean,
    has_terrace boolean,
    has_garden boolean,
    has_elevator boolean,
    parking_available boolean,
    is_furnished boolean,
    price_per_sqm_eur numeric(12,2) GENERATED ALWAYS AS (
CASE
    WHEN ((list_price_eur_cents IS NOT NULL) AND (COALESCE(living_area_sqm, usable_area_sqm) IS NOT NULL) AND (COALESCE(living_area_sqm, usable_area_sqm) > (0)::numeric)) THEN round((((list_price_eur_cents)::numeric / 100.0) / COALESCE(living_area_sqm, usable_area_sqm)), 2)
    ELSE NULL::numeric
END) STORED,
    completeness_score numeric(5,2) DEFAULT 0 NOT NULL,
    current_score numeric(5,2),
    normalization_version integer DEFAULT 1 NOT NULL,
    content_fingerprint character(64) NOT NULL,
    normalized_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    first_published_at timestamp with time zone,
    last_price_change_at timestamp with time zone,
    last_content_change_at timestamp with time zone,
    last_status_change_at timestamp with time zone,
    last_scored_at timestamp with time zone,
    search_vector tsvector GENERATED ALWAYS AS (to_tsvector('german'::regconfig, ((COALESCE(title, ''::text) || ' '::text) || COALESCE(description, ''::text)))) STORED,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    geocode_source text,
    geocode_updated_at timestamp with time zone,
    building_fact_id bigint,
    building_match_confidence text,
    contact_name text,
    contact_company text,
    contact_email public.citext,
    contact_phone text,
    geocode_attempts smallint DEFAULT 0 NOT NULL,
    geocode_next_attempt_at timestamp with time zone,
    CONSTRAINT chk_listings_time_order CHECK ((last_seen_at >= first_seen_at)),
    CONSTRAINT listings_balcony_area_sqm_check CHECK (((balcony_area_sqm IS NULL) OR (balcony_area_sqm >= (0)::numeric))),
    CONSTRAINT listings_commission_eur_cents_check CHECK (((commission_eur_cents IS NULL) OR (commission_eur_cents >= 0))),
    CONSTRAINT listings_completeness_score_check CHECK (((completeness_score >= (0)::numeric) AND (completeness_score <= (100)::numeric))),
    CONSTRAINT listings_current_score_check CHECK (((current_score IS NULL) OR ((current_score >= (0)::numeric) AND (current_score <= (100)::numeric)))),
    CONSTRAINT listings_district_no_check CHECK (((district_no IS NULL) OR ((district_no >= 1) AND (district_no <= 23)))),
    CONSTRAINT listings_garden_area_sqm_check CHECK (((garden_area_sqm IS NULL) OR (garden_area_sqm >= (0)::numeric))),
    CONSTRAINT listings_geocode_precision_check CHECK (((geocode_precision IS NULL) OR (geocode_precision = ANY (ARRAY['source_exact'::text, 'source_approx'::text, 'street'::text, 'estimated'::text, 'district'::text, 'city'::text, 'none'::text])))),
    CONSTRAINT listings_latitude_check CHECK (((latitude IS NULL) OR ((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric)))),
    CONSTRAINT listings_list_price_eur_cents_check CHECK (((list_price_eur_cents IS NULL) OR (list_price_eur_cents >= 0))),
    CONSTRAINT listings_listing_status_check CHECK ((listing_status = ANY (ARRAY['active'::text, 'inactive'::text, 'sold'::text, 'rented'::text, 'withdrawn'::text, 'expired'::text, 'unknown'::text]))),
    CONSTRAINT listings_living_area_sqm_check CHECK (((living_area_sqm IS NULL) OR (living_area_sqm > (0)::numeric))),
    CONSTRAINT listings_longitude_check CHECK (((longitude IS NULL) OR ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric)))),
    CONSTRAINT listings_monthly_operating_cost_eur_cents_check CHECK (((monthly_operating_cost_eur_cents IS NULL) OR (monthly_operating_cost_eur_cents >= 0))),
    CONSTRAINT listings_normalization_version_check CHECK ((normalization_version > 0)),
    CONSTRAINT listings_operation_type_check CHECK ((operation_type = ANY (ARRAY['sale'::text, 'rent'::text]))),
    CONSTRAINT listings_postal_code_check CHECK (((postal_code IS NULL) OR ((postal_code)::text ~ '^[0-9]{4}$'::text))),
    CONSTRAINT listings_property_type_check CHECK ((property_type = ANY (ARRAY['apartment'::text, 'house'::text, 'land'::text, 'commercial'::text, 'parking'::text, 'other'::text]))),
    CONSTRAINT listings_reserve_fund_eur_cents_check CHECK (((reserve_fund_eur_cents IS NULL) OR (reserve_fund_eur_cents >= 0))),
    CONSTRAINT listings_rooms_check CHECK (((rooms IS NULL) OR (rooms > (0)::numeric))),
    CONSTRAINT listings_terrace_area_sqm_check CHECK (((terrace_area_sqm IS NULL) OR (terrace_area_sqm >= (0)::numeric))),
    CONSTRAINT listings_usable_area_sqm_check CHECK (((usable_area_sqm IS NULL) OR (usable_area_sqm > (0)::numeric))),
    CONSTRAINT listings_year_built_check CHECK (((year_built IS NULL) OR ((year_built >= 1800) AND (year_built <= 2100))))
);

