    median_ppsqm_eur numeric(12,2) NOT NULL,
    trimmed_mean_ppsqm_eur numeric(12,2),
    p25_ppsqm_eur numeric(12,2),
    p75_ppsqm_eur numeric(12,2),
    stddev_ppsqm_eur numeric(12,2),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT market_baselines_district_no_check CHECK (((district_no IS NULL) OR ((district_no >= 1) AND (district_no <= 23)))),
    CONSTRAINT market_baselines_median_ppsqm_eur_check CHECK ((median_ppsqm_eur >= (0)::numeric)),
