    browser_version text,
    pages_fetched integer DEFAULT 0 NOT NULL,
    listings_discovered integer DEFAULT 0 NOT NULL,
    raw_snapshots_created integer DEFAULT 0 NOT NULL,
    normalized_created integer DEFAULT 0 NOT NULL,
    normalized_updated integer DEFAULT 0 NOT NULL,
    http_2xx integer DEFAULT 0 NOT NULL,
    http_4xx integer DEFAULT 0 NOT NULL,
    http_5xx integer DEFAULT 0 NOT NULL,
    captcha_count integer DEFAULT 0 NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    error_code text,
    error_message text,
    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_scrape_runs_time_order CHECK (((started_at IS NULL) OR (finished_at IS NULL) OR (finished_at >= started_at))),
    CONSTRAINT scrape_runs_captcha_count_check CHECK ((captcha_count >= 0)),
    CONSTRAINT scrape_runs_http_2xx_check CHECK ((http_2xx >= 0)),
    CONSTRAINT scrape_runs_http_4xx_check CHECK ((http_4xx >= 0)),
    CONSTRAINT scrape_runs_http_5xx_check CHECK ((http_5xx >= 0)),
    CONSTRAINT scrape_runs_listings_discovered_check CHECK ((listings_discovered >= 0)),
    CONSTRAINT scrape_runs_normalized_created_check CHECK ((normalized_created >= 0)),
    CONSTRAINT scrape_runs_normalized_updated_check CHECK ((normalized_updated >= 0)),
    CONSTRAINT scrape_runs_pages_fetched_check CHECK ((pages_fetched >= 0)),
    CONSTRAINT scrape_runs_raw_snapshots_created_check CHECK ((raw_snapshots_created >= 0)),
    CONSTRAINT scrape_runs_retry_count_check CHECK ((retry_count >= 0)),
    CONSTRAINT scrape_runs_scope_check CHECK ((scope = ANY (ARRAY['discovery'::text, 'detail'::text, 'full'::text]))),
    CONSTRAINT scrape_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'partial'::text, 'failed'::text, 'cancelled'::text, 'rate_limited'::text]))),
    CONSTRAINT scrape_runs_trigger_type_check CHECK ((trigger_type = ANY (ARRAY['schedule'::text, 'manual'::text, 'backfill'::text, 'retry'::text, 'recovery'::text])))
);

