    postal_codes text[] DEFAULT ARRAY[]::text[] NOT NULL,
    min_price_eur_cents bigint,
    max_price_eur_cents bigint,
    min_area_sqm numeric(10,2),
    max_area_sqm numeric(10,2),
    min_rooms numeric(4,1),
    max_rooms numeric(4,1),
    required_keywords text[] DEFAULT ARRAY[]::text[] NOT NULL,
    excluded_keywords text[] DEFAULT ARRAY[]::text[] NOT NULL,
    min_score numeric(5,2),
    sort_by text DEFAULT 'score_desc'::text NOT NULL,
    alert_frequency text DEFAULT 'instant'::text NOT NULL,
    alert_channels text[] DEFAULT ARRAY['in_app'::text] NOT NULL,
