    CONSTRAINT chk_user_filters_price_range CHECK (((min_price_eur_cents IS NULL) OR (max_price_eur_cents IS NULL) OR (max_price_eur_cents >= min_price_eur_cents))),
    CONSTRAINT chk_user_filters_rooms_range CHECK (((min_rooms IS NULL) OR (max_rooms IS NULL) OR (max_rooms >= min_rooms))),
    CONSTRAINT user_filters_alert_frequency_check CHECK ((alert_frequency = ANY (ARRAY['instant'::text, 'hourly_digest'::text, 'daily_digest'::text, 'manual'::text]))),
    CONSTRAINT user_filters_filter_kind_check CHECK ((filter_kind = ANY (ARRAY['listing_search'::text, 'alert'::text]))),
    CONSTRAINT user_filters_max_area_sqm_check CHECK (((max_area_sqm IS NULL) OR (max_area_sqm >= (0)::numeric))),
    CONSTRAINT user_filters_max_price_eur_cents_check CHECK (((max_price_eur_cents IS NULL) OR (max_price_eur_cents >= 0))),
    CONSTRAINT user_filters_max_rooms_check CHECK (((max_rooms IS NULL) OR (max_rooms >= (0)::numeric))),
    CONSTRAINT user_filters_min_area_sqm_check CHECK (((min_area_sqm IS NULL) OR (min_area_sqm >= (0)::numeric))),
    CONSTRAINT user_filters_min_price_eur_cents_check CHECK (((min_price_eur_cents IS NULL) OR (min_price_eur_cents >= 0))),
    CONSTRAINT user_filters_min_rooms_check CHECK (((min_rooms IS NULL) OR (min_rooms >= (0)::numeric))),
    CONSTRAINT user_filters_min_score_check CHECK (((min_score IS NULL) OR ((min_score >= (0)::numeric) AND (min_score <= (100)::numeric)))),
    CONSTRAINT user_filters_operation_type_check CHECK (((operation_type IS NULL) OR (operation_type = ANY (ARRAY['sale'::text, 'rent'::text])))),
    CONSTRAINT user_filters_sort_by_check CHECK ((sort_by = ANY (ARRAY['score_desc'::text, 'newest'::text, 'price_asc'::text, 'price_desc'::text, 'sqm_desc'::text])))
);

